result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_gcs.py", "content": """"Tests for the Glasgow Coma Scale fixture (educational, synthetic data).

Valid GCS components: eye 1-4, verbal 1-5, motor 1-6. Minimum total is 3,
maximum is 15. Classification: severe <= 8, moderate 9-12, mild >= 13.
"""
import pytest

from gcs import classify, gcs_total


class TestGcsTotal:
    def test_minimum_total_is_3(self):
        assert gcs_total(1, 1, 1) == 3

    def test_maximum_total_is_15(self):
        assert gcs_total(4, 5, 6) == 15

    def test_typical_score(self):
        assert gcs_total(3, 4, 5) == 12

    @pytest.mark.parametrize("component", [0])
    def test_zero_components_rejected(self, component):
        with pytest.raises(ValueError):
            gcs_total(component, component, component)

    def test_eye_above_range_rejected(self):
        with pytest.raises(ValueError):
            gcs_total(5, 1, 1)

    def test_verbal_above_range_rejected(self):
        with pytest.raises(ValueError):
            gcs_total(1, 6, 1)

    def test_motor_above_range_rejected(self):
        with pytest.raises(ValueError):
            gcs_total(1, 1, 7)


class TestClassify:
    def test_severe_boundary_at_8(self):
        assert classify(8) == "severe"

    def test_severe_minimum(self):
        assert classify(3) == "severe"

    def test_moderate_starts_at_9(self):
        assert classify(9) == "moderate"

    def test_moderate_upper_boundary(self):
        assert classify(12) == "moderate"

    def test_mild_starts_at_13(self):
        assert classify(13) == "mild"

    def test_mild_maximum(self):
        assert classify(15) == "mild"
"})
print(result)

